CREATE OR REPLACE FUNCTION public.rh_save_config(p_data jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s jsonb:=p_data->'settings'; v jsonb; c jsonb; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Sem permissão'; END IF; IF jsonb_typeof(s->'pesos')<>'object' OR jsonb_typeof(s->'pontos_transporte')<>'object' OR jsonb_typeof(s->'pontos_computador')<>'object' OR jsonb_typeof(s->'faixas_permanencia')<>'array' THEN RAISE EXCEPTION 'Configuração inválida'; END IF; IF (SELECT sum(value::numeric) FROM jsonb_each_text(s->'pesos'))<>100 OR EXISTS(SELECT 1 FROM jsonb_each_text(s->'pesos') WHERE value::numeric<0 OR value::numeric>100) THEN RAISE EXCEPTION 'Os pesos devem somar 100 pontos'; END IF; IF (s->>'pontos_sem_experiencia')::numeric NOT BETWEEN 0 AND 15 OR (s->>'pontos_bairro_max')::numeric NOT BETWEEN 0 AND 4 OR (s->>'teto_transporte')::numeric NOT BETWEEN 0 AND 10 THEN RAISE EXCEPTION 'Faixas de pontos inválidas'; END IF; IF EXISTS(SELECT 1 FROM jsonb_each_text(s->'pontos_computador') WHERE value::numeric NOT BETWEEN 0 AND 5) OR EXISTS(SELECT 1 FROM jsonb_each_text(s->'pontos_transporte') WHERE value::numeric NOT BETWEEN 0 AND 10) OR EXISTS(SELECT 1 FROM jsonb_array_elements(s->'faixas_permanencia') f WHERE (f->>'pontos')::numeric NOT BETWEEN 0 AND 15) THEN RAISE EXCEPTION 'Pontuação inválida'; END IF; IF s->>'aviso_instancia_id' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM whatsapp_numbers_safe WHERE id=(s->>'aviso_instancia_id')::uuid AND provider='uazapi') THEN RAISE EXCEPTION 'Escolha uma instância uazapi'; END IF; UPDATE rh_settings SET guia_atendimento=left(s->>'guia_atendimento',10000),pesos=s->'pesos',faixas_permanencia=s->'faixas_permanencia',pontos_sem_experiencia=(s->>'pontos_sem_experiencia')::numeric,pontos_transporte=s->'pontos_transporte',pontos_bairro_max=(s->>'pontos_bairro_max')::numeric,teto_transporte=(s->>'teto_transporte')::numeric,pontos_computador=s->'pontos_computador',aviso_numero=left(s->>'aviso_numero',20),aviso_instancia_id=(s->>'aviso_instancia_id')::uuid,aviso_ativo=coalesce((s->>'aviso_ativo')::boolean,false),updated_at=now(),updated_by=auth.uid() WHERE id=1 AND (to_jsonb(rh_settings)-'updated_at'-'updated_by'-'ai_blocked_reason') IS DISTINCT FROM (s-'updated_at'-'updated_by'-'ai_blocked_reason'); FOR v IN SELECT * FROM jsonb_array_elements(p_data->'vagas') LOOP UPDATE rh_vagas SET titulo=left(v->>'titulo',200),resumo=left(v->>'resumo',3000) WHERE id=(v->>'id')::uuid AND (titulo IS DISTINCT FROM v->>'titulo' OR resumo IS DISTINCT FROM v->>'resumo'); END LOOP; FOR c IN SELECT * FROM jsonb_array_elements(p_data->'cenarios') LOOP UPDATE rh_cenarios SET contexto=left(c->>'contexto',2000),mensagem_cliente=left(c->>'mensagem_cliente',2000),gabarito=left(c->>'gabarito',3000) WHERE id=(c->>'id')::uuid AND (contexto IS DISTINCT FROM c->>'contexto' OR mensagem_cliente IS DISTINCT FROM c->>'mensagem_cliente' OR gabarito IS DISTINCT FROM c->>'gabarito'); END LOOP; RETURN true; END $$; REVOKE ALL ON FUNCTION public.rh_save_config(jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.rh_save_config(jsonb) TO authenticated,service_role;